package config

import (
	"fmt"
)

type Config struct {
	Host       string
	ListenPort int
}

func DefaultConfig() *Config {
	return &Config{Host: "localhost", ListenPort: 8080}
}

func (c *Config) Addr() string {
	return fmt.Sprintf("%s:%d", c.Host, c.ListenPort)
}
